(58, 'EXA-0031', 'Hormona Estimulante De La Tiroides (Tsh)', 'Es una hormona producida por la glándula pituitaria que estimula la tiroides para que produzca las hormonas T3 y T4. Un análisis de TSH mide la cantidad de esta hormona en la sangre y se utiliza para evaluar la función tiroidea.', 'Inmunologia Especial', 'Quimioluminiscencia', '3 horas', 'Ayuno de 8 horas', '', 'Suero', 'Tapa Roja', '', 70.00, '[{\"id_parametro\":\"param_1764206097178_472094\",\"tipo\":\"Parámetro\",\"nombre\":\"TSH\",\"metodologia\":\"CLIA\",\"unidad\":\"uUI\\/mL\",\"opciones\":[],\"referencias\":[{\"valor\":\"0.40 - 4.90\",\"desc\":\"\",\"valor_min\":\"0.40\",\"valor_max\":\"4.90\",\"sexo\":\"cualquiera\",\"edad_min\":\"0\",\"edad_max\":\"100\"}],\"formula\":\"\",\"negrita\":false,\"cursiva\":false,\"alineacion\":\"left\",\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"decimales\":2,\"rows\":4,\"orden\":1}]', 1),
