(62, 'EXA-0035', 'Serología Cualitativa Rpr-Sífilis', '', 'Inmunología', 'Floculación/Manual', '1 hora', '', '', 'Suero', 'Tapa Roja', '', 15.00, '[{\"id_parametro\":\"param_1764077079_327416\",\"tipo\":\"Parámetro\",\"nombre\":\"RPR \",\"metodologia\":\"Aglutinacion\",\"unidad\":\"\",\"opciones\":[],\"referencias\":[{\"valor\":\"SUERO NO REACTIVO\",\"desc\":\"\",\"valor_min\":\"\",\"valor_max\":\"\",\"sexo\":\"cualquiera\",\"edad_min\":\"0\",\"edad_max\":\"100\"}],\"formula\":\"\",\"negrita\":false,\"cursiva\":false,\"alineacion\":\"left\",\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"rows\":4,\"orden\":1}]', 1),
(63, 'EXA-0036', 'Vih Prueba Rapida', 'Es importante recordar que un resultado positivo en una prueba rápida debe ser confirmado por pruebas de laboratorio', 'Inmunología', 'Cromatografía', '1 hora', '', '', 'Suero', 'Tapa Roja', '', 45.00, '[{\"tipo\":\"Parámetro\",\"nombre\":\"VIH\",\"metodologia\":\"Cromatografía\",\"unidad\":\"\",\"opciones\":[],\"referencias\":[{\"valor\":\"SUERO NO REACTIVO\",\"desc\":\"\",\"edad_min\":0,\"edad_max\":100,\"valor_min\":\"SUERO NO REACTIVO\",\"valor_max\":\"SUERO NO REACTIVO\"}],\"formula\":\"\",\"negrita\":false,\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"orden\":1,\"id_parametro\":\"param_1764077079_559740\"}]', 1),
(64, 'EXA-0037', 'Amilasa Serica', 'Es una enzima que ayuda a descomponer los carbohidratos, facilitando su digestión. Se produce principalmente en el páncreas y las glándulas salivales.', 'Bioquímica', 'Cinética', '1 hora', 'Ayuno de 8 horas', '', 'Suero', 'Tapa Roja', '', 25.00, '[{\"id_parametro\":\"param_1765465893423_200445\",\"tipo\":\"Parámetro\",\"nombre\":\"Amilasa\",\"metodologia\":\"Cinetica\",\"unidad\":\"U/L\",\"opciones\":[],\"referencias\":[{\"valor\":\"< 86\",\"desc\":\"\",\"valor_min\":\"0\",\"valor_max\":\"86\",\"sexo\":\"cualquiera\",\"edad_min\":\"0\",\"edad_max\":\"100\"}],\"formula\":\"\",\"negrita\":false,\"cursiva\":false,\"alineacion\":\"left\",\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"orden\":1}]', 1),
(65, 'EXA-0038', 'Lipasa', 'Es una prueba que mide la cantidad de una enzima llamada lipasa en la sangre. La lipasa es producida principalmente por el páncreas y ayuda a digerir las grasas de los alimentos. Los niveles elevados de lipasa en la sangre pueden indicar problemas con el páncreas, como pancreatitis.', 'Bioquímica', 'Cinética', '1 hora', 'Ayuno de 8 horas', '', 'Suero', 'Tapa Roja', '', 40.00, '[{\"id_parametro\":\"param_1765465931847_487173\",\"tipo\":\"Parámetro\",\"nombre\":\"Lipasa\",\"metodologia\":\"Cinetica\",\"unidad\":\"U/L\",\"opciones\":[],\"referencias\":[{\"valor\":\"≤ 38\",\"desc\":\"\",\"valor_min\":\"0\",\"valor_max\":\"37\",\"sexo\":\"cualquiera\",\"edad_min\":\"0\",\"edad_max\":\"100\"}],\"formula\":\"\",\"negrita\":false,\"cursiva\":false,\"alineacion\":\"left\",\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"orden\":1}]', 1),
(66, 'EXA-0039', 'Ca 125 (Ovario)', 'La prueba CA 125 mide los niveles de una proteína llamada antígeno del cáncer 125 en la sangre, la cual puede ser un marcador tumoral.', 'Inmunologia Especial', 'Clia', '2 horas', 'Ayuno de 8 horas', '', 'Suero', 'Tapa Roja', '', 70.00, '[{\"id_parametro\":\"param_1764252893028_38770\",\"tipo\":\"Parámetro\",\"nombre\":\"CA 125\",\"metodologia\":\"Elisa\",\"unidad\":\"U\\/ml\",\"opciones\":[],\"referencias\":[{\"valor\":\"< 36\",\"desc\":\"\",\"valor_min\":\"0\",\"valor_max\":\"36\",\"sexo\":\"cualquiera\",\"edad_min\":\"0\",\"edad_max\":\"100\"}],\"formula\":\"\",\"negrita\":false,\"cursiva\":false,\"alineacion\":\"left\",\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"rows\":4,\"orden\":1}]', 1),
(67, 'EXA-0040', 'Ca 15-3', 'Es un marcador tumoral, específicamente una proteína, que se utiliza principalmente en el seguimiento del cáncer de mama.', 'Inmunologia Especial', 'Quimioluminiscencia', '2 horas', 'Ayuno de 8 horas', '', 'Suero', 'Tapa Roja', '', 75.00, '[{\"tipo\":\"Parámetro\",\"nombre\":\"CA 15-3\",\"metodologia\":\" Quimioluminiscencia\",\"unidad\":\"UI\\/ml\",\"opciones\":[],\"referencias\":[{\"valor\":\"< 25\",\"desc\":\"\",\"edad_min\":0,\"edad_max\":100,\"valor_min\":\"< 25\",\"valor_max\":\"< 25\"}],\"formula\":\"\",\"negrita\":false,\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"orden\":1,\"id_parametro\":\"param_1764077079_356464\"}]', 1),
(68, 'EXA-0041', 'T3 Libre', 'Es una forma de la hormona triyodotironina (T3) que circula libremente en la sangre, no está unida a proteínas y es biológicamente activa, es decir, puede entrar a las células y ejercer su efecto.', 'Inmunologia Especial', 'Clia', '2 horas', 'Ayuno de 8 horas', '', 'Suero', 'Tapa Roja', '', 70.00, '[{\"id_parametro\":\"param_1770159257300_97970\",\"tipo\":\"Parámetro\",\"nombre\":\"T3 LIBRE\",\"metodologia\":\"CLIA\",\"unidad\":\"pg\\/ml\",\"opciones\":[],\"referencias\":[{\"valor\":\"1.40 - 4.20\",\"desc\":\"\",\"valor_min\":\"1.4\",\"valor_max\":\"4.2\",\"sexo\":\"cualquiera\",\"edad_min\":\"0\",\"edad_max\":\"100\"}],\"formula\":\"\",\"negrita\":false,\"cursiva\":false,\"alineacion\":\"left\",\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"decimales\":1,\"rows\":4,\"orden\":1}]', 1),
(69, 'EXA-0042', 'T4 Libre', 'Es la forma activa de la hormona tiroxina que no está unida a proteínas en la sangre, permitiendo que entre en las células y ejerza sus efectos en el metabolismo y crecimiento. Se mide en un análisis de sangre para evaluar la función tiroidea.', 'Inmunologia Especial', 'Clia', '2h', 'Ayuno de 8 horas', '', 'Suero', 'Tapa Roja', '', 70.00, '[{\"id_parametro\":\"param_1764077079_549836\",\"tipo\":\"Parámetro\",\"nombre\":\"T4 LIBRE\",\"metodologia\":\"CLIA\",\"unidad\":\"pmol\\/L\",\"opciones\":[],\"referencias\":[{\"valor\":\"12.0 -22.0\",\"desc\":\"\",\"valor_min\":\"12\",\"valor_max\":\"22\",\"sexo\":\"cualquiera\",\"edad_min\":\"0\",\"edad_max\":\"12.0\",\"alerta_modo\":\"both\",\"alerta_color\":\"#c62828\",\"alerta_textos\":\"\",\"alerta_colores_texto\":\"\"}],\"formula\":\"\",\"template_text\":\"\",\"negrita\":false,\"cursiva\":false,\"alineacion\":\"left\",\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"decimales\":2,\"rows\":4,\"orden\":1},{\"id_parametro\":\"param_1784917353865_158505\",\"tipo\":\"Parámetro\",\"nombre\":\"\",\"metodologia\":\"\",\"unidad\":\"\",\"opciones\":[],\"referencias\":[],\"formula\":\"\",\"template_text\":\"\",\"negrita\":false,\"cursiva\":false,\"alineacion\":\"left\",\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"rows\":4,\"orden\":2}]', 1),
(70, 'EXA-0043', 'Perfil Tiroideo', 'Es un conjunto de análisis de sangre que evalúan la función de la glándula tiroides. Estas pruebas miden los niveles de diferentes hormonas tiroideas en la sangre, como la TSH (hormona estimulante de la tiroides), T4 (tiroxina) y T3 (triyodotironina), para ayudar a diagnosticar y monitorear enfermedades de la tiroides como el hipotiroidismo y el hipertiroidismo.', 'Inmunologia Especial', 'Clia', '3 horas', 'Ayuno de 8 horas', '', 'Suero', 'Tapa Roja', '', 180.00, '[{\"id_parametro\":\"param_1768225388128_220913\",\"tipo\":\"Parámetro\",\"nombre\":\"TSH\",\"metodologia\":\"CLIA\",\"unidad\":\"uIU\\/ml\",\"opciones\":[],\"referencias\":[{\"valor\":\"0.40 - 4.90\",\"desc\":\"\",\"valor_min\":\"0.28\",\"valor_max\":\"6.82\",\"sexo\":\"cualquiera\",\"edad_min\":\"0\",\"edad_max\":\"100\"}],\"formula\":\"\",\"negrita\":false,\"cursiva\":false,\"alineacion\":\"left\",\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"rows\":4,\"orden\":1},{\"id_parametro\":\"param_1768225388128_501775\",\"tipo\":\"Parámetro\",\"nombre\":\"T3 TOTAL\",\"metodologia\":\"CLIA\",\"unidad\":\"ng\\/mL\",\"opciones\":[],\"referencias\":[{\"valor\":\"1.23 -3.07\",\"desc\":\"\",\"valor_min\":\"1.23\",\"valor_max\":\"3.07\",\"sexo\":\"cualquiera\",\"edad_min\":\"0\",\"edad_max\":\"120\"}],\"formula\":\"\",\"negrita\":false,\"cursiva\":false,\"alineacion\":\"left\",\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"rows\":4,\"orden\":2},{\"id_parametro\":\"param_1768225388128_913286\",\"tipo\":\"Parámetro\",\"nombre\":\"T4 LIBRE\",\"metodologia\":\"CLIA\",\"unidad\":\"ng\\/dL\",\"opciones\":[],\"referencias\":[{\"valor\":\"0.90 - 1.75\",\"desc\":\"\",\"valor_min\":\"0.9\",\"valor_max\":\"1.75\",\"sexo\":\"cualquiera\",\"edad_min\":\"0\",\"edad_max\":\"100\"}],\"formula\":\"\",\"negrita\":false,\"cursiva\":false,\"alineacion\":\"left\",\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"rows\":4,\"orden\":3}]', 1),
(71, 'EXA-0044', 'Prolactina', 'Es una hormona producida principalmente por la glándula pituitaria, ubicada en la base del cerebro. Su función principal es estimular la producción de leche materna (lactancia) durante el embarazo y después del parto.', 'Inmunología', 'Elisa', '2 horas', 'Ayuno de 8 horas', '', 'Suero', 'Tapa Roja', '', 80.00, '[{\"id_parametro\":\"param_1765831786146_576058\",\"tipo\":\"Parámetro\",\"nombre\":\"PROLACTINA \",\"metodologia\":\"Elisa\",\"unidad\":\"ng\\/ml\",\"opciones\":[],\"referencias\":[{\"valor\":\" 1.2 - 19.5\",\"desc\":\"Adulta\",\"valor_min\":\"1.2\",\"valor_max\":\"19.5\",\"sexo\":\"cualquiera\",\"edad_min\":\"0\",\"edad_max\":\"100\"},{\"valor\":\"1.5 - 18.5\",\"desc\":\"Posmenopausica\",\"valor_min\":\"1.5\",\"valor_max\":\"18.5\",\"sexo\":\"cualquiera\",\"edad_min\":\"0\",\"edad_max\":\"100\"},{\"valor\":\" 1.8 - 17.0 \",\"desc\":\"Hombre\",\"valor_min\":\"1.8\",\"valor_max\":\"17\",\"sexo\":\"cualquiera\",\"edad_min\":\"0\",\"edad_max\":\"100\"}],\"formula\":\"\",\"negrita\":false,\"cursiva\":false,\"alineacion\":\"left\",\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"decimales\":2,\"rows\":4,\"orden\":1}]', 1),
(72, 'EXA-0045', 'Insulina', 'La insulina es una hormona producida por el páncreas que ayuda a regular los niveles de azúcar en la sangre.', 'Inmunología', 'Elisa', '3 horas', 'Ayuno de 8 horas', '', 'Suero', 'Tapa Roja', '', 70.00, '[{\"id_parametro\":\"param_1764972589344_422969\",\"tipo\":\"Parámetro\",\"nombre\":\"Insulina\",\"metodologia\":\"Elisa\",\"unidad\":\"µlU\\/ml\",\"opciones\":[],\"referencias\":[{\"valor\":\"3 - 25\",\"desc\":\"\",\"valor_min\":\"3\",\"valor_max\":\"25\",\"sexo\":\"cualquiera\",\"edad_min\":\"0\",\"edad_max\":\"100\"}],\"formula\":\"\",\"negrita\":false,\"cursiva\":false,\"alineacion\":\"left\",\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"rows\":4,\"orden\":1}]', 1),
(73, 'EXA-0046', 'Testosterona Total', 'Es una prueba de sangre que mide la cantidad total de la hormona testosterona presente en el cuerpo, incluyendo tanto la que está unida a proteínas como la que no', 'Inmunología', 'Elisa', '2 horas', 'Ayuno de 8 horas', '', 'Suero', 'Tapa Roja', '', 70.00, '[{\"id_parametro\":\"param_1770671642684_776968\",\"tipo\":\"Parámetro\",\"nombre\":\"Testosterona Total\",\"metodologia\":\"Elisa\",\"unidad\":\"ng\\/ml\",\"opciones\":[],\"referencias\":[{\"valor\":\"2.5 - 10.0\",\"desc\":\"Masculino\",\"valor_min\":\"2.5\",\"valor_max\":\"10\",\"sexo\":\"masculino\",\"edad_min\":\"0\",\"edad_max\":\"120\",\"alerta_modo\":\"both\",\"alerta_color\":\"#c62828\",\"alerta_textos\":\"\",\"alerta_colores_texto\":\"\"},{\"valor\":\"0.2 - 0.95\",\"desc\":\"Femenino\",\"valor_min\":\"0.2\",\"valor_max\":\"0.95\",\"sexo\":\"femenino\",\"edad_min\":\"0\",\"edad_max\":\"120\",\"alerta_modo\":\"both\",\"alerta_color\":\"#c62828\",\"alerta_textos\":\"\",\"alerta_colores_texto\":\"\"},{\"valor\":\"0.1 - 3.7\",\"desc\":\"Niños antes de la pubertad\",\"valor_min\":\"0.1\",\"valor_max\":\"3.7\",\"sexo\":\"cualquiera\",\"edad_min\":\"6\",\"edad_max\":\"11\",\"alerta_modo\":\"both\",\"alerta_color\":\"#c62828\",\"alerta_textos\":\"\",\"alerta_colores_texto\":\"\"}],\"formula\":\"\",\"template_text\":\"\",\"negrita\":false,\"cursiva\":false,\"alineacion\":\"left\",\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"rows\":4,\"orden\":1}]', 1);
