(74, 'EXA-0047', 'Testosterona Libre', 'La testosterona libre está más disponible para que el cuerpo la use al desarrollar músculos y huesos. Sin embargo, la mayoría de su testosterona está unida a proteínas como la globulina fijadora de hormonas sexuales.', 'Inmunología', 'Elisa', '2 horas', 'Ayuno de 8 horas', '', 'Suero', 'Tapa Roja', '', 75.00, '[{\"id_parametro\":\"param_1768939961360_564739\",\"tipo\":\"Parámetro\",\"nombre\":\"Testosterona Libre \",\"metodologia\":\"Elisa\",\"unidad\":\"pg\\/ml\",\"opciones\":[],\"referencias\":[{\"valor\":\" 9.2-34.6\",\"desc\":\"Varon de 20-39 años\",\"valor_min\":\"9.2\",\"valor_max\":\"34.6\",\"sexo\":\"masculino\",\"edad_min\":\"0\",\"edad_max\":\"120\"},{\"valor\":\"6.1-30.3\",\"desc\":\"Varón de 40-59 años\",\"valor_min\":\"6.1\",\"valor_max\":\"30.3\",\"sexo\":\"masculino\",\"edad_min\":\"0\",\"edad_max\":\"120\"},{\"valor\":\"6.1-27.9\",\"desc\":\"Varón de ≥60 años\",\"valor_min\":\"6.1\",\"valor_max\":\"27.9\",\"sexo\":\"masculino\",\"edad_min\":\"0\",\"edad_max\":\"120\"},{\"valor\":\"0.2-6.1\",\"desc\":\"Mujer de 20-39 años\",\"valor_min\":\"0.2\",\"valor_max\":\"6.1\",\"sexo\":\"femenino\",\"edad_min\":\"0\",\"edad_max\":\"120\"},{\"valor\":\"0.3-4.4\",\"desc\":\"Mujer de 40-59 años\",\"valor_min\":\"0.3\",\"valor_max\":\"4.4\",\"sexo\":\"femenino\",\"edad_min\":\"0\",\"edad_max\":\"120\"},{\"valor\":\"0.5-3.4\",\"desc\":\"Mujer de ≥60 años\",\"valor_min\":\"0.5\",\"valor_max\":\"3.4\",\"sexo\":\"femenino\",\"edad_min\":\"0\",\"edad_max\":\"120\"}],\"formula\":\"\",\"negrita\":false,\"cursiva\":false,\"alineacion\":\"left\",\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"decimales\":1,\"rows\":4,\"orden\":1}]', 1),
