(86, 'EXA-0059', 'Gamma Glutamil Transferasa(Ggt)', 'Es una enzima que se encuentra principalmente en el hígado, pero también en otros órganos como el riñón y el páncreas. Se usa en análisis de sangre para evaluar la salud del hígado y las vías biliares.', 'Bioquimica', 'Cinetica', '1 hora', 'Ayuno de 8 horas', '', 'Suero', 'Rojo', '', 40.00, '[{\"tipo\":\"Parámetro\",\"nombre\":\"GAMMA GLUTAMIL TRANSFERASA(GGT)\",\"metodologia\":\"Cinetica\",\"unidad\":\"UI\\/L\",\"opciones\":[],\"referencias\":[{\"valor\":\"( < 50 )\",\"desc\":\"Varones\",\"edad_min\":0,\"edad_max\":100,\"valor_min\":\"( < 50 )\",\"valor_max\":\"( < 50 )\"},{\"valor\":\"( < 35 )\",\"desc\":\"Mujeres\",\"edad_min\":0,\"edad_max\":100,\"valor_min\":\"( < 35 )\",\"valor_max\":\"( < 35 )\"}],\"formula\":\"\",\"negrita\":false,\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"orden\":1,\"id_parametro\":\"param_1764077079_197718\"}]', 1),
