(155, 'EXA-0128', 'Cociente Alb/Crea', 'El cociente albúmina/creatinina sirve para detectar niveles altos de proteínas en la orina (albuminuria) y es la primera prueba para evaluar la función renal. Para realizar estos cálculos, el laboratorio solo necesita una muestra de tu orina.', 'Bioquímica', 'Enzimatico', '1 hora', '', '', 'Orina', 'Frasco Tapa Rosca', '', 30.00, '[{\"id_parametro\":\"param_1764079581113_644903\",\"tipo\":\"Subtítulo\",\"nombre\":\"COCIENTE ALB\\/CREAT\",\"metodologia\":\"\",\"unidad\":\"\",\"opciones\":[],\"referencias\":[],\"formula\":\"\",\"negrita\":false,\"cursiva\":false,\"alineacion\":\"left\",\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"rows\":4,\"orden\":1},{\"id_parametro\":\"param_1764079581113_403396\",\"tipo\":\"Parámetro\",\"nombre\":\"ALBUMINURIA\",\"metodologia\":\"ENZI\",\"unidad\":\"mg\\/dl\",\"opciones\":[],\"referencias\":[{\"valor\":\"<25\",\"desc\":\"\",\"valor_min\":\"0\",\"valor_max\":\"25\",\"sexo\":\"cualquiera\",\"edad_min\":\"0\",\"edad_max\":\"100\"}],\"formula\":\"\",\"negrita\":false,\"cursiva\":false,\"alineacion\":\"left\",\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"decimales\":1,\"rows\":4,\"orden\":2},{\"id_parametro\":\"param_1764079581113_850159\",\"tipo\":\"Parámetro\",\"nombre\":\"CREATININA EN ORINA\",\"metodologia\":\"CINETICO\",\"unidad\":\"mg\\/dl\",\"opciones\":[],\"referencias\":[{\"valor\":\"27-300\",\"desc\":\"\",\"valor_min\":\"27\",\"valor_max\":\"300\",\"sexo\":\"cualquiera\",\"edad_min\":\"0\",\"edad_max\":\"100\"}],\"formula\":\"\",\"negrita\":false,\"cursiva\":false,\"alineacion\":\"left\",\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"rows\":4,\"orden\":3},{\"id_parametro\":\"param_1764079581114_571284\",\"tipo\":\"Parámetro\",\"nombre\":\"CAC\",\"metodologia\":\"CALCULO\",\"unidad\":\"mg\\/g\",\"opciones\":[],\"referencias\":[{\"valor\":\"<30\",\"desc\":\"De normal a ligeramente elevado\",\"valor_min\":\"0\",\"valor_max\":\"30\",\"sexo\":\"cualquiera\"