(188, 'EXA-0161', 'Test De Graham', 'El Test de Graham es una prueba diagnóstica simple para detectar el parásito intestinal oxiuro (Enterobius vermicularis) usando una cinta adhesiva transparente aplicada en la zona perianal para recolectar huevos, que luego se examinan al microscopio, siendo crucial hacerlo a primera hora de la mañana y sin asearse previamente para capturar los huevos que las hembras depositan por la noche.', 'Parasitologia', 'Microscopia / Manual', '1 hora', '', '', 'Heces', 'Frasco Tapa Rosca', '', 15.00, '[{\"id_parametro\":\"param_1766516837791_839826\",\"tipo\":\"Parámetro\",\"nombre\":\"Test De Graham\",\"metodologia\":\"Microscopia / Manual\",\"unidad\":\"\",\"opciones\":[],\"referencias\":[{\"valor\":\"\",\"desc\":\"(Negativo)\",\"valor_min\":\"\",\"valor_max\":\"\",\"sexo\":\"cualquiera\",\"edad_min\":\"\",\"edad_max\":\"\"}],\"formula\":\"\",\"negrita\":true,\"cursiva\":false,\"alineacion\":\"left\",\"color_texto\":\"#000000\",\"color_fondo\":\"#ffffff\",\"rows\":4,\"orden\":1}]', 1),
